import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    interface Action { void run(); }

    public static void main(String[] args) {
        Solution.AddressCommand addressCommand = new Solution.AddressCommand("", null);
        Solution.Address address = Solution.mapAddress(addressCommand);
        eq("", address.getStreet(), "empty street copied");
        eq(null, address.getCity(), "null city copied");
        eq("", addressCommand.getStreet(), "address command mutated");

        List<String> emails = new ArrayList<String>();
        emails.add("a@example.test");
        emails.add("");
        emails.add("a@example.test");
        Solution.NewProfileCommand command = new Solution.NewProfileCommand(
                null, -7, new Solution.AddressCommand("Street", "City"), emails);
        Solution.Profile profile = Solution.mapProfile(command);

        eq(null, profile.getName(), "name copied without validation");
        eq(-7, profile.getAge(), "age copied without validation");
        eq("Street", profile.getAddress().getStreet(), "street");
        eq("City", profile.getAddress().getCity(), "city");
        eq(Arrays.asList("a@example.test", "", "a@example.test"), profile.getEmails(),
                "email order and duplicates");

        emails.clear();
        emails.add("changed@example.test");
        eq(Arrays.asList("a@example.test", "", "a@example.test"), profile.getEmails(),
                "email snapshot");
        expectUnsupported(new Action() { public void run() { profile.getEmails().add("x"); }});

        List<String> emptyEmails = new ArrayList<String>();
        Solution.Profile empty = Solution.mapProfile(new Solution.NewProfileCommand(
                "Name", 0, new Solution.AddressCommand(null, null), emptyEmails));
        eq(0, empty.getEmails().size(), "empty email list");
        eq(null, empty.getAddress().getStreet(), "null street copied");

        expectIllegal(new Action() { public void run() { Solution.mapAddress(null); }});
        expectIllegal(new Action() { public void run() { Solution.mapProfile(null); }});
        expectIllegal(new Action() { public void run() {
            Solution.mapProfile(new Solution.NewProfileCommand("N", 1, null, new ArrayList<String>()));
        }});
        expectIllegal(new Action() { public void run() {
            Solution.mapProfile(new Solution.NewProfileCommand("N", 1,
                    new Solution.AddressCommand("S", "C"), null));
        }});

        final List<String> withNull = new ArrayList<String>();
        withNull.add("valid");
        withNull.add(null);
        withNull.add("also-valid");
        expectIllegal(new Action() { public void run() {
            Solution.mapProfile(new Solution.NewProfileCommand("N", 1,
                    new Solution.AddressCommand("S", "C"), withNull));
        }});
        eq(3, withNull.size(), "invalid input list mutated");
        eq(null, withNull.get(1), "null element removed");
    }

    static void expectIllegal(Action action) {
        try { action.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }

    static void expectUnsupported(Action action) {
        try { action.run(); throw new AssertionError("expected UnsupportedOperationException"); }
        catch (UnsupportedOperationException expected) { }
    }

    static void eq(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message);
    }

    static void eq(Object expected, Object actual, String message) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
        }
    }
}

